import React, { useEffect, useState } from 'react';
import { Typography, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from '@mui/material';

function FlakyTestsPage() {
  const [tests, setTests] = useState([]);

  useEffect(() => {
    fetch('/api/flaky-tests')
      .then((res) => res.json())
      .then(setTests);
  }, []);

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Flaky Tests
      </Typography>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Test Name</TableCell>
              <TableCell>Module</TableCell>
              <TableCell>Flaky Score</TableCell>
              <TableCell>Risk Level</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {tests.map((row) => (
              <TableRow key={`${row.test_name}-${row.module_name}`}>
                <TableCell>{row.test_name}</TableCell>
                <TableCell>{row.module_name}</TableCell>
                <TableCell>{row.flaky_score}%</TableCell>
                <TableCell>{row.risk_level}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </div>
  );
}

export default FlakyTestsPage;
